import os

contacts = {}

def add_contact(name, phone):
    contacts[name] = phone
    print(f"Added: {name} → {phone}")

def find_contact(name):
    if name in contacts:
        print(f"{name}: {contacts[name]}")
    else:
        print(f"{name}: Not found")

def save_contacts():
    with open("contacts.txt", "w") as f:
        for name, phone in contacts.items():
            f.write(f"{name}:{phone}\n")

add_contact("Priya", "9876543210")
add_contact("Ravi", "9123456789")
add_contact("Meera", "9988776655")
save_contacts()

find_contact("Ravi")
find_contact("Karan")

rooms = {
    "Hall": {"north": "Kitchen", "south": "Garden"},
    "Kitchen": {"south": "Hall", "east": "Pantry"},
    "Garden": {"north": "Hall"},
    "Pantry": {}
}

current_room = "Hall"

print("=== TEXT ADVENTURE ===")
print("Find the treasure! Type directions to move. Type 'quit' to exit.\n")

moves = ["north", "east"]

for move in moves:
    print(f"You are in: {current_room}")
    exits = list(rooms[current_room].keys())
    print(f"Exits: {', '.join(exits)}")
    print(f"You go {move}...")

    if move in rooms[current_room]:
        current_room = rooms[current_room][move]
    else:
        print("You can't go that way!")

    if current_room == "Pantry":
        print("You found the treasure! You win!")
        break
    print()
